SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS users (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 login VARCHAR(32) NOT NULL UNIQUE,
 password_hash VARCHAR(255) NOT NULL,
 role ENUM('user','developer','founder') NOT NULL DEFAULT 'user',
 is_active TINYINT(1) NOT NULL DEFAULT 1,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 last_login_at TIMESTAMP NULL,
 last_seen_at TIMESTAMP NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS sessions_meta (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,last_used_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,ip_address VARCHAR(45),user_agent VARCHAR(255),INDEX(user_id),CONSTRAINT fk_sm_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS system_settings (`key` VARCHAR(100) PRIMARY KEY,`value` TEXT NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,updated_by BIGINT UNSIGNED NULL,CONSTRAINT fk_ss_user FOREIGN KEY(updated_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO system_settings(`key`,`value`) VALUES ('registration_enabled','1') ON DUPLICATE KEY UPDATE `key`=`key`;
CREATE TABLE IF NOT EXISTS todo_lists (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(160) NOT NULL,description TEXT NULL,created_by BIGINT UNSIGNED NOT NULL,position INT NOT NULL DEFAULT 0,is_archived TINYINT(1) NOT NULL DEFAULT 0,visibility ENUM('TEAM_ONLY','SELECTED_USERS','PUBLIC_READ') NOT NULL DEFAULT 'TEAM_ONLY',public_slug VARCHAR(64) NULL UNIQUE,show_task_authors_publicly TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_tl_user FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS todo_categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,todo_list_id BIGINT UNSIGNED NOT NULL,title VARCHAR(120) NOT NULL,position INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(todo_list_id,position),CONSTRAINT fk_tc_list FOREIGN KEY(todo_list_id) REFERENCES todo_lists(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tasks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,todo_list_id BIGINT UNSIGNED NOT NULL,category_id BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,description TEXT NULL,created_by BIGINT UNSIGNED NOT NULL,position INT NOT NULL DEFAULT 0,version INT NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(todo_list_id),INDEX(category_id,position),INDEX(created_by),CONSTRAINT fk_task_list FOREIGN KEY(todo_list_id) REFERENCES todo_lists(id) ON DELETE CASCADE,CONSTRAINT fk_task_cat FOREIGN KEY(category_id) REFERENCES todo_categories(id) ON DELETE RESTRICT,CONSTRAINT fk_task_user FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tags (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE,color VARCHAR(20) NULL,created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_tag_user FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS task_tags (task_id BIGINT UNSIGNED NOT NULL,tag_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(task_id,tag_id),CONSTRAINT fk_tt_task FOREIGN KEY(task_id) REFERENCES tasks(id) ON DELETE CASCADE,CONSTRAINT fk_tt_tag FOREIGN KEY(tag_id) REFERENCES tags(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS todo_list_viewers (todo_list_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,granted_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(todo_list_id,user_id),CONSTRAINT fk_tlv_list FOREIGN KEY(todo_list_id) REFERENCES todo_lists(id) ON DELETE CASCADE,CONSTRAINT fk_tlv_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_tlv_granter FOREIGN KEY(granted_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS todo_audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,todo_list_id BIGINT UNSIGNED NOT NULL,task_id BIGINT UNSIGNED NULL,actor_user_id BIGINT UNSIGNED NOT NULL,action VARCHAR(80) NOT NULL,from_category_id BIGINT UNSIGNED NULL,to_category_id BIGINT UNSIGNED NULL,before_data JSON NULL,after_data JSON NULL,metadata JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(todo_list_id,created_at),INDEX(actor_user_id,created_at),INDEX(action),CONSTRAINT fk_al_list FOREIGN KEY(todo_list_id) REFERENCES todo_lists(id) ON DELETE CASCADE,CONSTRAINT fk_al_actor FOREIGN KEY(actor_user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,type VARCHAR(80) NOT NULL,title VARCHAR(255) NOT NULL,description TEXT NULL,actor_user_id BIGINT UNSIGNED NULL,target_user_id BIGINT UNSIGNED NULL,todo_list_id BIGINT UNSIGNED NULL,task_id BIGINT UNSIGNED NULL,metadata JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(created_at),CONSTRAINT fk_ev_actor FOREIGN KEY(actor_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
